// Формируем дату для вчерашнего дня
const yesterday = new Date();
yesterday.setDate(yesterday.getDate() - 1);

const day = String(yesterday.getDate()).padStart(2, '0');
const month = String(yesterday.getMonth() + 1).padStart(2, '0');
const year = yesterday.getFullYear();

const dateStr = `${day}.${month}.${year}`;

console.log(`📅 Запрос курса НБК за: ${dateStr}`);

return { json: { date: dateStr } };

const xmlData = $input.first().json.data || $input.first().json;

// Парсим XML от НБК
let exchangeRate = 480; // По умолчанию

try {
  // Ищем USD в XML (код валюты USD)
  const usdMatch = xmlData.match(/<item>.*?<title>USD<\/title>.*?<description>(\d+\.?\d*)<\/description>.*?<\/item>/s);

  if (usdMatch && usdMatch[1]) {
    exchangeRate = parseFloat(usdMatch[1]);
    console.log(`✅ НБК курс USD → KZT: ${exchangeRate}₸`);
  } else {
    console.warn('⚠️ Не удалось получить курс от НБК, используем резервный: 480₸');
  }
} catch (error) {
  console.error('❌ Ошибка парсинга курса НБК:', error.message);
  console.warn('⚠️ Используем резервный курс: 480₸');
}

return { json: { exchangeRate } };

const fbInput = $input.first().json;
const currencyInput = $input.all()[0].json;

if (!fbInput || !fbInput.data || fbInput.data.length === 0) {
  console.log('⚠️ Нет данных от Facebook за вчера');
  return { json: { skip: true, reason: 'no_data' } };
}

const fbData = fbInput.data[0];

// Получаем курс USD → KZT от НБК
const exchangeRate = currencyInput?.exchangeRate || 480;
console.log(`💱 Курс НБК USD → KZT: ${exchangeRate}₸`);

const projectId = '64c94e87-630c-470e-8ab1-8f7c8c835efa';

// Вчерашняя дата
const yesterday = new Date();
yesterday.setDate(yesterday.getDate() - 1);
const yesterdayStr = yesterday.toISOString().split('T')[0];

function safeParse(value, decimals = 2) {
  const num = parseFloat(value || 0);
  return isNaN(num) ? 0 : parseFloat(num.toFixed(decimals));
}

function safeInt(value) {
  const num = parseInt(value || 0, 10);
  return isNaN(num) ? 0 : num;
}

function extractAction(actions, actionTypes) {
  if (!actions || !Array.isArray(actions)) return 0;

  for (const type of actionTypes) {
    const action = actions.find(a => a.action_type === type);
    if (action) {
      const val = safeInt(action.value);
      if (val > 0) console.log(`   ✅ ${type}: ${val}`);
      return val;
    }
  }
  return 0;
}

console.log(`\n📅 Обработка данных за: ${yesterdayStr}`);

const leads = extractAction(fbData.actions, [
  'lead',
  'leadgen_grouped',
  'onsite_conversion.lead_grouped'
]);

const conversations = extractAction(fbData.actions, [
  'onsite_conversion.messaging_conversation_started_7d',
  'onsite_conversion.messaging_first_reply',
  'onsite_conversion.messaging_conversation_started_1d'
]);

const totalLeads = leads + conversations;

// Конвертируем spend из USD в KZT БЕЗ КОПЕЕК
const spendUSD = safeParse(fbData.spend, 2);
const spendKZT = Math.round(spendUSD * exchangeRate);  // Округляем!

console.log(`💰 Spend: $${spendUSD} → ${spendKZT}₸ (курс: ${exchangeRate})`);

const result = {
  project_id: projectId,
  date: yesterdayStr,
  spend: spendKZT,  // В тенге! ✅
  impressions: safeInt(fbData.impressions),
  clicks: safeInt(fbData.clicks),
  leads: totalLeads,  // leads + conversations
  diagnostics: 0,
  sales: 0,
  revenue: 0,
  skip: false,
  _meta: {
    spend_usd: spendUSD,
    exchange_rate: exchangeRate,
    fb_leads: leads,
    fb_conversations: conversations
  }
};

console.log(`✅ Результат:`);
console.log(`   Spend: ${spendKZT}₸`);
console.log(`   Impressions: ${result.impressions}`);
console.log(`   Clicks: ${result.clicks}`);
console.log(`   Leads: ${totalLeads} (forms: ${leads}, messages: ${conversations})`);

return { json: result };

const data = $input.first().json;

console.log('\n🎉 УСПЕШНО СИНХРОНИЗИРОВАНО!');
console.log('================================');
console.log(`📅 Дата: ${data.date}`);
console.log(`💰 Spend: ${data.spend}₸`);
console.log(`👁️  Impressions: ${data.impressions}`);
console.log(`🖱️  Clicks: ${data.clicks}`);
console.log(`📝 Leads: ${data.leads}`);
console.log('================================\n');

return { 
  json: { 
    success: true, 
    date: data.date,
    message: `✅ Данные за ${data.date} синхронизированы`
  } 
};
